def escape_js(s):
    # Escape quotes and backslashes for js string literal
    return s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n')

with open('assets/js/i18n-site.js', 'r', encoding='utf-8') as f:
    code = f.read()

# For each language, find its block and update or insert keys
for lang, keys_dict in UPDATES.items():
    # Find language block: lang: { ... }
    m = re.search(r'(' + re.escape(lang) + r'\s*:\s*\{)(.*?)(\n\s*\},)', code, re.DOTALL)
    if not m:
        print(f"Error: block for {lang} not found!")
        continue
    
    header = m.group(1)
    body = m.group(2)
    footer = m.group(3)
    
    for key, val in keys_dict.items():
        escaped_val = escape_js(val)
        # Check if key exists in body
        key_pattern = r'(^\s*' + re.escape(key) + r'\s*:\s*)(?:\"(?:[^\"\\]|\\.)*\"|\'(?:[^\'\\]|\\.)*\')(,?)'
        if re.search(key_pattern, body, re.MULTILINE):
            # Replace
            body = re.sub(
                key_pattern,
                r'\1"' + escaped_val + r'"\2',
                body,
                flags=re.MULTILINE
            )
        else:
            # Append key before end
            body += f'\n      {key}: "{escaped_val}",'
            
    code = code[:m.start()] + header + body + footer + code[m.end():]

with open('assets/js/i18n-site.js', 'w', encoding='utf-8') as f:
    f.write(code)

print("Updated assets/js/i18n-site.js successfully!")
